from typing import List

def unique_digits(x: List[int]) -> List[int]:
    def has_even_digit(n: int) -> bool:
        while n > 0:
            digit = n % 10
            if digit % 2 == 0:
                return True
            n = n // 10
        return False

    result = [num for num in x if not has_even_digit(num)]
    return sorted(result)
```

